      overview: 'A comprehensive quiz testing your understanding of liberation (Kaivalya), witness consciousness, and the path to absolute freedom.',
      mainContent: `This quiz challenges your grasp of Patanjali's teachings on Kaivalya -- absolute independence, the state where consciousness recognizes its true nature completely free from identification with mind, body, or experience.

**Key concepts tested:**
- The distinction between Purusha (consciousness) and Prakriti (nature)
- Witness consciousness versus mental states
- The role of the three gunas in bondage and liberation
- Common confusions between advanced practice and actual liberation
- The practical meaning of Kaivalya in daily life

These aren't just intellectual questions. Each one points to a lived distinction that determines whether you're deepening in freedom or subtly maintaining identification.

If you miss questions, use them as pointers -- areas where conceptual clarity can support direct recognition.

Remember: understanding Kaivalya intellectually is helpful, but Kaivalya itself is the direct recognition of what you are beyond all understanding. Let these questions serve the recognition, not replace it.`,
      keyTakeaway: 'Liberation (Kaivalya) isn\'t a special state to achieve but the recognition of what you already are -- consciousness itself, free from identification with any content of experience.',
